const item = $input.first().json;
const secret = $env.SHOP_OWNER_WEBHOOK_SECRET;
const headers = item.headers || {};
const body = (item.body && typeof item.body === 'object') ? item.body : item;
const isWebhook = !!(headers.host || headers.Host);
const headerSecret = String(headers['x-shop-webhook-secret'] || headers['X-Shop-Webhook-Secret'] || '');
const bodySecret = String(body.webhookSecret || '');
const authorized = isWebhook
  ? (!!secret && (headerSecret === secret || bodySecret === secret))
  : true;

let below = body.below !== undefined && body.below !== '' ? Number(body.below) : 2;
if (!Number.isFinite(below) || below < 1) below = 2;
const force = body.force === true || body.force === 'true' || body.force === 1;

let error = '';
let httpStatus = 200;
if (isWebhook && !authorized) { error = 'Unauthorized webhook'; httpStatus = 401; }

const hasTelegram = !!(String($env.TELEGRAM_BOT_TOKEN || '').trim() && String($env.TELEGRAM_CHAT_ID || '').trim());
if (!error && !hasTelegram) { error = 'TELEGRAM_BOT_TOKEN or TELEGRAM_CHAT_ID is not set'; httpStatus = 500; }

return [{ json: {
  ok: !error, error, httpStatus, isWebhook, below, force,
  telegramChatId: String($env.TELEGRAM_CHAT_ID || '').trim(),
  apiBase: $env.API_BASE_URL || 'http://backend:8080/api'
} }];

const ctx = $input.first().json;
const api = ctx.apiBase;
const below = ctx.below;
const force = !!ctx.force;
const unwrap = (res) => {
  if (Array.isArray(res)) return res;
  if (Array.isArray(res?.data?.records)) return res.data.records;
  if (Array.isArray(res?.data)) return res.data;
  return res?.data ?? res;
};
const http = async (url) => {
  const res = await this.helpers.httpRequest({
    method: 'GET', url, json: true, ignoreHttpStatusErrors: true, returnFullResponse: true
  });
  const status = res.statusCode || res.status || 200;
  const payload = res.body !== undefined ? res.body : res;
  if (status >= 400) {
    const err = payload?.error || payload?.title || payload?.message || `HTTP ${status}`;
    const e = new Error(String(err));
    e.statusCode = status;
    throw e;
  }
  return payload;
};

try {
  const offers = [];
  let page = 1;
  const pageSize = 100;
  let totalPages = 1;
  while (page <= totalPages && page <= 20) {
    const raw = await http(`${api}/ProductOffers?page=${page}&pageSize=${pageSize}&onlyActives=false`);
    const records = unwrap(raw) || [];
    const list = Array.isArray(records) ? records : [];
    offers.push(...list);
    const meta = raw?.data || raw;
    totalPages = Number(meta?.totalPages || meta?.TotalPages || 1) || 1;
    if (list.length < pageSize) break;
    page += 1;
  }

  const low = offers
    .filter(o => !o.isDeleted)
    .map(o => ({
      offerId: o.id,
      productId: o.productId,
      name: o.productName || o.name || `offer-${o.id}`,
      inventory: Number(o.inventory),
      isActive: !!o.isActive,
      price: o.basePrice ?? o.finalPrice
    }))
    .filter(o => Number.isFinite(o.inventory) && o.inventory < below)
    .sort((a, b) => a.inventory - b.inventory || a.offerId - b.offerId);

  const staticData = $getWorkflowStaticData('global');
  const prev = (staticData.lowStock && typeof staticData.lowStock === 'object') ? { ...staticData.lowStock } : {};
  const toAlert = [];
  for (const o of low) {
    const key = String(o.offerId);
    const last = prev[key];
    if (!force && last !== undefined && Number(last) === o.inventory) continue;
    toAlert.push(o);
    prev[key] = o.inventory;
  }
  for (const key of Object.keys(prev)) {
    if (!low.some(o => String(o.offerId) === key)) delete prev[key];
  }
  staticData.lowStock = prev;

  if (!toAlert.length) {
    return [{ json: {
      ok: true, httpStatus: 200, isWebhook: ctx.isWebhook, below, force,
      scanned: offers.length, lowCount: low.length, alertCount: 0, skippedNotify: true,
      telegramChatId: ctx.telegramChatId,
      textFa: low.length
        ? `موجودی کم: ${low.length} مورد (بدون تغییر نسبت به هشدار قبلی)`
        : `موجودی کم: موردی با موجودی < ${below} نیست.`
    } }];
  }

  const lines = toAlert.map(o => {
    const state = o.isActive ? 'فعال' : 'پیش‌نویس';
    return `#${o.offerId} ${o.name}\n  موجودی: ${o.inventory} | productId: ${o.productId} | ${state}`;
  });
  let textFa = [`⚠️ هشدار موجودی کم (< ${below})`, `تعداد: ${toAlert.length}`, '', ...lines].join('\n');
  if (textFa.length > 3900) textFa = textFa.slice(0, 3890) + '\n…';

  return [{ json: {
    ok: true, httpStatus: 200, isWebhook: ctx.isWebhook, below, force,
    scanned: offers.length, lowCount: low.length, alertCount: toAlert.length, skippedNotify: false,
    telegramChatId: ctx.telegramChatId, textFa, items: toAlert
  } }];
} catch (e) {
  return [{ json: { ok: false, httpStatus: e.statusCode || 502, isWebhook: ctx.isWebhook, error: e.message || String(e) } }];
}

const scan = $('Scan Low Stock').item.json;
const tg = $input.first().json;
const status = tg.statusCode || tg.status || 200;
const body = tg.body !== undefined ? tg.body : tg;
const tgOk = status < 400 && body?.ok !== false;
if (!tgOk) {
  return [{ json: {
    ok: false, httpStatus: 502, isWebhook: scan.isWebhook,
    error: body?.description || body?.error || `Telegram HTTP ${status}`,
    alertCount: scan.alertCount, lowCount: scan.lowCount
  } }];
}
return [{ json: {
  ok: true, httpStatus: 200, isWebhook: scan.isWebhook,
  alertCount: scan.alertCount, lowCount: scan.lowCount, scanned: scan.scanned,
  notified: true, textFa: scan.textFa
} }];

const scan = $input.first().json;
return [{ json: {
  ok: true, httpStatus: 200, isWebhook: scan.isWebhook,
  alertCount: 0, lowCount: scan.lowCount, scanned: scan.scanned,
  notified: false, skippedNotify: true, textFa: scan.textFa
} }];
